70	/** Horizontal scroller without native scrollbars: floating start/end buttons, wheel and focus scrolling. */
71	export function HorizontalScrollArea(props: HorizontalScrollAreaProps) {
72	    const { children } = props;
73	    const scrollerRef = useRef<HTMLDivElement>(null);
74	    const contentRef = useRef<HTMLDivElement>(null);
75	    const [scrollState, setScrollState] = useState<ScrollState>(NO_SCROLL);
76	
77	    const updateScrollState = useCallback(() => {
78	        const scroller = scrollerRef.current;
79	        const content = contentRef.current;
80	        if (!scroller || !content) return;
81	        const nextState = measureScrollState(scroller, content);
82	        setScrollState(current => isSameScrollState(current, nextState) ? current : nextState);
83	    }, []);
84	
85	    useEffect(() => {
86	        const scroller = scrollerRef.current;
87	        const content = contentRef.current;
88	        if (!scroller || !content) return;
89	
90	        const handleWheel = (event: WheelEvent) => {
91	            if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
92	            if (content.scrollWidth <= scroller.clientWidth) return;
93	            event.preventDefault();
94	            scroller.scrollLeft += event.deltaY;
95	        };
96	        const handleFocusIn = (event: FocusEvent) => {
97	            if (!(event.target instanceof HTMLElement)) return;
98	            event.target.scrollIntoView({ block: 'nearest', inline: 'nearest' });
99	        };
100	        const resizeObserver = new ResizeObserver(updateScrollState);
101	        resizeObserver.observe(scroller);
102	        resizeObserver.observe(content);
103	        scroller.addEventListener('scroll', updateScrollState);
104	        scroller.addEventListener('wheel', handleWheel, { passive: false });
105	        scroller.addEventListener('focusin', handleFocusIn);
106	        updateScrollState();
107	
108	        return () => {
109	            resizeObserver.disconnect();
110	            scroller.removeEventListener('scroll', updateScrollState);
111	            scroller.removeEventListener('wheel', handleWheel);
112	            scroller.removeEventListener('focusin', handleFocusIn);
113	        };
114	    }, [updateScrollState]);
115	
116	    const scrollToStart = useCallback(() => {
117	        scrollerRef.current?.scrollBy({ behavior: 'smooth', left: -SCROLL_STEP });
118	    }, []);
119	    const scrollToEnd = useCallback(() => {
120	        scrollerRef.current?.scrollBy({ behavior: 'smooth', left: SCROLL_STEP });
121	    }, []);
122	
123	    const { canScrollEnd, canScrollStart } = scrollState;
124	
125	    return (
126	        <Box sx={rootSx}>
127	            {canScrollStart ? (
128	                <Box sx={startButtonContainerSx}>
129	                    <IconButton aria-label="Scroll left" onClick={scrollToStart} size="small">
130	                        <ChevronLeft fontSize="small" />
131	                    </IconButton>
132	                </Box>
133	            ) : null}
134	            <Box ref={scrollerRef} sx={scrollerSx}>
135	                <Box ref={contentRef} sx={contentSx}>
136	                    {children}
137	                </Box>
138	            </Box>
139	            {canScrollEnd ? (
140	                <Box sx={endButtonContainerSx}>
141	                    <IconButton aria-label="Scroll right" onClick={scrollToEnd} size="small">
142	                        <ChevronRight fontSize="small" />
143	                    </IconButton>
144	                </Box>
145	            ) : null}
146	        </Box>
147	    );
148	}
