28	    const content = screen.getByRole('button', { name: 'First' }).parentElement;
29	    const scroller = content?.parentElement;
30	    if (!content || !scroller) throw new Error('Expected scroll area structure');
31	    const layout: ScrollLayout = { contentWidth, scrollLeft };
32	    const scrollBy = vi.fn();
33	    Object.defineProperties(content, { scrollWidth: { configurable: true, get: () => layout.contentWidth } });
34	    Object.defineProperties(scroller, {
35	        clientWidth: { configurable: true, get: () => SCROLLER_WIDTH },
36	        scrollBy: { configurable: true, value: scrollBy },
37	        scrollLeft: {
38	            configurable: true,
39	            get: () => layout.scrollLeft,
40	            set: (value: number) => { layout.scrollLeft = value; },
41	        },
42	        scrollWidth: { configurable: true, get: () => layout.contentWidth },
43	    });
44	    fireEvent.scroll(scroller);
45	
46	    return { layout, scrollBy, scroller };
